import sys
import csv
import json


def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    path = sys.argv[1]
    totals = {}
    with open(path, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        try:
            next(reader)  # skip header
        except StopIteration:
            pass
        for row in reader:
            if len(row) < 2:
                continue
            item_raw = row[0]
            qty_raw = row[1]
            # Normalize item: collapse whitespace to single spaces, then casefold
            norm_item = ' '.join(item_raw.split()).casefold()
            if not norm_item:
                continue
            # Parse quantity: blank means 1, otherwise nonnegative base-10 int
            qty_str = qty_raw.strip()
            if qty_str == '':
                qty = 1
            else:
                qty = int(qty_str)
            totals[norm_item] = totals.get(norm_item, 0) + qty

    result = [{"item": k, "quantity": totals[k]} for k in sorted(totals.keys())]
    print(json.dumps(result, ensure_ascii=False))


if __name__ == '__main__':
    main()
